package net.officefloor.hq.app.project;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.client.Client;
import net.officefloor.hq.app.client.ClientRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class ProjectService {

    private final ProjectRepository projects;
    private final ClientRepository clients;
    private final Audit audit;

    public ProjectService(ProjectRepository projects, ClientRepository clients, Audit audit) {
        this.projects = projects;
        this.clients = clients;
        this.audit = audit;
    }

    /**
     * The projects, leaving out archived ones unless they are asked for, and only those carrying the
     * given tag when one is given.
     */
    @Transactional(readOnly = true)
    public List<ProjectResponse> list(boolean includeArchived, Long tagId) {
        List<Project> found;
        if (tagId == null) {
            found = includeArchived ? projects.findAllWithClient() : projects.findActiveWithClient();
        } else {
            found = includeArchived ? projects.findAllByTagIdWithClient(tagId)
                    : projects.findActiveByTagIdWithClient(tagId);
        }
        return found.stream().map(ProjectResponse::from).toList();
    }

    @Transactional(readOnly = true)
    public List<ProjectResponse> listForClient(Long clientId) {
        if (!clients.existsById(clientId)) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client");
        }
        return projects.findActiveByClientIdWithClient(clientId).stream().map(ProjectResponse::from).toList();
    }

    @Transactional(readOnly = true)
    public ProjectResponse get(Long id) {
        return projects.findByIdWithClient(id).map(ProjectResponse::from)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown project"));
    }

    @Transactional
    public ProjectResponse create(ProjectRequest request) {
        Client client = clients.findById(request.clientId())
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST, "Unknown client"));
        Project project = new Project(request.name().trim(), client);
        if (request.status() != null) {
            project.setStatus(request.status());
        }
        Project saved = projects.save(project);
        return ProjectResponse.from(saved);
    }

    /** Marks a project active, on hold or finished, recording the change in the audit log. */
    @Transactional
    public ProjectResponse changeStatus(Long id, ProjectStatus status) {
        Project project = projects.findByIdWithClient(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown project"));
        if (project.getStatus() != status) {
            project.setStatus(status);
            projects.flush();
            audit.record("PROJECT_STATUS_CHANGED id=" + id + " status=" + status);
        }
        return ProjectResponse.from(project);
    }

    /**
     * Archives a project: it drops off the project lists but is kept, with its tasks and invoices,
     * and the archiving is recorded in the audit log.
     */
    @Transactional
    public ProjectResponse archive(Long id) {
        Project project = projects.findByIdWithClient(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown project"));
        if (!project.isArchived()) {
            project.setArchived(true);
            projects.flush();
            audit.record("PROJECT_ARCHIVED id=" + id);
        }
        return ProjectResponse.from(project);
    }

    /** Brings an archived project back onto the project lists, recording it in the audit log. */
    @Transactional
    public ProjectResponse restore(Long id) {
        Project project = projects.findByIdWithClient(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown project"));
        if (project.isArchived()) {
            project.setArchived(false);
            projects.flush();
            audit.record("PROJECT_RESTORED id=" + id);
        }
        return ProjectResponse.from(project);
    }
}
package net.officefloor.hq.app.project;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

public interface ProjectRepository extends JpaRepository<Project, Long> {

    /** All projects with their client loaded in the same query. */
    @Query("SELECT p FROM Project p JOIN FETCH p.client ORDER BY p.id")
    List<Project> findAllWithClient();

    /** All projects not archived, with their client loaded in the same query. */
    @Query("SELECT p FROM Project p JOIN FETCH p.client WHERE p.archived = false ORDER BY p.id")
    List<Project> findActiveWithClient();

    /** All projects carrying a tag, with their client loaded in the same query. */
    @Query("SELECT p FROM Project p JOIN FETCH p.client JOIN p.tags t WHERE t.id = :tagId ORDER BY p.id")
    List<Project> findAllByTagIdWithClient(Long tagId);

    /** All projects not archived carrying a tag, with their client loaded in the same query. */
    @Query("SELECT p FROM Project p JOIN FETCH p.client JOIN p.tags t WHERE t.id = :tagId"
            + " AND p.archived = false ORDER BY p.id")
    List<Project> findActiveByTagIdWithClient(Long tagId);

    /** A client's projects not archived, with their client loaded in the same query. */
    @Query("SELECT p FROM Project p JOIN FETCH p.client c WHERE c.id = :clientId AND p.archived = false"
            + " ORDER BY p.id")
    List<Project> findActiveByClientIdWithClient(Long clientId);

    /** One project with its client loaded in the same query. */
    @Query("SELECT p FROM Project p JOIN FETCH p.client WHERE p.id = :id")
    Optional<Project> findByIdWithClient(Long id);

    /** How many projects a client has. */
    long countByClientId(Long clientId);

    /** Whether any invoice has been raised against the project. */
    @Query("SELECT COUNT(i) > 0 FROM Invoice i WHERE i.project.id = :id")
    boolean hasInvoices(Long id);
}
import { Component, inject, signal } from '@angular/core';
import { NonNullableFormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { RouterLink } from '@angular/router';
import { Client, ClientService } from '../clients/client.service';
import { Tag, TagService } from '../tags/tag.service';
import { PROJECT_STATUSES, Project, ProjectService, ProjectStatus } from './project.service';

// Projects page: add a project for a client and list all projects with their client's name; each
// project opens its detail page and can be archived once it is no longer needed. Archived projects
// are kept but left off the list unless the archived toggle is on, where they can be restored. The
// list can be narrowed to the projects carrying a chosen tag. Each project is marked active, on hold
// or finished, chosen when it is added and changeable from its row.
@Component({
  selector: 'app-projects',
  imports: [ReactiveFormsModule, RouterLink],
  template: `
    <h1>Projects</h1>

    <form [formGroup]="form" (ngSubmit)="submit()" data-testid="project-form" novalidate>
      <div>
        <label for="project-name">Name</label>
        <input
          id="project-name"
          type="text"
          formControlName="name"
          data-testid="project-form-name"
          [attr.aria-invalid]="showError('name')"
          [attr.aria-describedby]="showError('name') ? 'project-name-error' : null"
        />
        @if (showError('name')) {
          <p id="project-name-error" role="alert" data-testid="project-form-name-error">
            Name is required.
          </p>
        }
      </div>
      <div>
        <label for="project-client">Client</label>
        <select
          id="project-client"
          formControlName="clientId"
          data-testid="project-form-client"
          [attr.aria-invalid]="showError('clientId')"
          [attr.aria-describedby]="showError('clientId') ? 'project-client-error' : null"
        >
          <option value="">Select a client</option>
          @for (c of clients(); track c.id) {
            <option [value]="c.id">{{ c.name }}</option>
          }
        </select>
        @if (showError('clientId')) {
          <p id="project-client-error" role="alert" data-testid="project-form-client-error">
            Choose a client.
          </p>
        }
      </div>
      <div>
        <label for="project-status">Status</label>
        <select id="project-status" formControlName="status" data-testid="project-form-status">
          @for (s of statuses; track s.value) {
            <option [value]="s.value">{{ s.label }}</option>
          }
        </select>
      </div>
      <button type="submit" data-testid="project-form-submit" [disabled]="saving()">
        Add project
      </button>
      @if (saveError()) {
        <p role="alert" data-testid="project-form-error">{{ saveError() }}</p>
      }
    </form>

    @if (deleteError()) {
      <p role="alert" data-testid="project-delete-error">{{ deleteError() }}</p>
    }

    <div>
      <input
        id="projects-show-archived"
        type="checkbox"
        data-testid="projects-show-archived"
        [checked]="showArchived()"
        (change)="toggleArchived()"
      />
      <label for="projects-show-archived">Show archived projects</label>
    </div>

    <div>
      <label for="project-tag-filter">Filter by tag</label>
      <select
        id="project-tag-filter"
        data-testid="project-tag-filter"
        #tagSelect
        [value]="tagFilter() ?? ''"
        (change)="filterByTag(tagSelect.value)"
      >
        <option value="">All tags</option>
        @for (t of tags(); track t.id) {
          <option [value]="t.id">{{ t.name }}</option>
        }
      </select>
    </div>

    @if (projects().length === 0) {
      <p data-testid="projects-empty">
        {{ tagFilter() === null ? 'No projects yet.' : 'No projects with this tag.' }}
      </p>
    } @else {
      <table data-testid="projects-table">
        <caption>All projects</caption>
        <thead>
          <tr>
            <th scope="col">Name</th>
            <th scope="col">Client</th>
            <th scope="col">Status</th>
            <th scope="col"><span class="visually-hidden">Actions</span></th>
          </tr>
        </thead>
        <tbody>
          @for (p of projects(); track p.id) {
            <tr [attr.data-testid]="'project-row-' + p.id">
              <td data-testid="project-name">
                {{ p.name }}
                @if (p.archived) {
                  <span [attr.data-testid]="'project-archived-' + p.id">(archived)</span>
                }
              </td>
              <td data-testid="project-client">{{ p.clientName }}</td>
              <td>
                <span data-testid="project-status">{{ p.status }}</span>
                <label class="visually-hidden" [for]="'project-status-select-' + p.id"
                  >Change status of {{ p.name }}</label
                >
                <select
                  #statusSelect
                  [id]="'project-status-select-' + p.id"
                  [attr.data-testid]="'project-status-select-' + p.id"
                  [value]="p.status"
                  [disabled]="deleting() === p.id"
                  (change)="changeStatus(p, statusSelect.value)"
                >
                  @for (s of statuses; track s.value) {
                    <option [value]="s.value">{{ s.label }}</option>
                  }
                </select>
              </td>
              <td>
                <a
                  [routerLink]="['/projects', p.id]"
                  [attr.data-testid]="'project-open-' + p.id"
                  [attr.aria-label]="'Open ' + p.name"
                  >Open</a
                >
                @if (p.archived) {
                  <button
                    type="button"
                    [attr.data-testid]="'project-restore-' + p.id"
                    [attr.aria-label]="'Restore ' + p.name"
                    [disabled]="deleting() === p.id"
                    (click)="restore(p)"
                  >
                    Restore
                  </button>
                } @else {
                  <!-- Deleting a project now archives it; the delete anchor is kept on the same control. -->
                  <span [attr.data-testid]="'project-delete-' + p.id">
                    <button
                      type="button"
                      [attr.data-testid]="'project-archive-' + p.id"
                      [attr.aria-label]="'Archive ' + p.name"
                      [disabled]="deleting() === p.id"
                      (click)="archive(p)"
                    >
                      Archive
                    </button>
                  </span>
                }
              </td>
            </tr>
          }
        </tbody>
      </table>
    }
  `,
})
export class Projects {
  private readonly service = inject(ProjectService);
  private readonly clientService = inject(ClientService);
  private readonly tagService = inject(TagService);

  protected readonly projects = signal<Project[]>([]);
  protected readonly clients = signal<Client[]>([]);
  protected readonly saving = signal(false);
  protected readonly saveError = signal<string | null>(null);
  protected readonly deleting = signal<number | null>(null);
  protected readonly deleteError = signal<string | null>(null);
  protected readonly showArchived = signal(false);
  protected readonly tags = signal<Tag[]>([]);
  protected readonly tagFilter = signal<number | null>(null);
  protected readonly statuses = PROJECT_STATUSES;

  protected readonly form = inject(NonNullableFormBuilder).group({
    name: ['', [Validators.required, Validators.maxLength(255)]],
    clientId: ['', Validators.required],
    status: ['ACTIVE' as ProjectStatus, Validators.required],
  });

  constructor() {
    this.load();
    this.clientService.list().subscribe((list) => this.clients.set(list));
    this.tagService.list().subscribe((list) => this.tags.set(list));
  }

  protected showError(field: 'name' | 'clientId'): boolean {
    const control = this.form.controls[field];
    return control.invalid && (control.touched || control.dirty);
  }

  protected submit(): void {
    if (this.form.invalid || !this.form.getRawValue().name.trim()) {
      this.form.markAllAsTouched();
      return;
    }
    const { name, clientId, status } = this.form.getRawValue();
    this.saving.set(true);
    this.saveError.set(null);
    this.service.create({ name: name.trim(), clientId: Number(clientId), status }).subscribe({
      next: (created) => {
        // A new project carries no tags, so it only belongs on an unfiltered list.
        if (this.tagFilter() === null) {
          this.projects.update((list) => [...list, created]);
        }
        this.form.reset();
        this.saving.set(false);
      },
      error: () => {
        this.saveError.set('Could not save the project. Please try again.');
        this.saving.set(false);
      },
    });
  }

  protected toggleArchived(): void {
    this.showArchived.update((show) => !show);
    this.load();
  }

  protected filterByTag(value: string): void {
    this.tagFilter.set(value === '' ? null : Number(value));
    this.load();
  }

  protected changeStatus(project: Project, status: string): void {
    this.deleting.set(project.id);
    this.deleteError.set(null);
    this.service.changeStatus(project.id, status as ProjectStatus).subscribe({
      next: (changed) => {
        this.projects.update((list) => list.map((p) => (p.id === changed.id ? changed : p)));
        this.deleting.set(null);
      },
      error: () => {
        this.deleteError.set(`Could not change the status of ${project.name}. Please try again.`);
        this.deleting.set(null);
      },
    });
  }

  protected archive(project: Project): void {
    this.deleting.set(project.id);
    this.deleteError.set(null);
    this.service.archive(project.id).subscribe({
      next: (archived) => {
        this.projects.update((list) =>
          this.showArchived()
            ? list.map((p) => (p.id === archived.id ? archived : p))
            : list.filter((p) => p.id !== archived.id),
        );
        this.deleting.set(null);
      },
      error: () => {
        this.deleteError.set(`Could not archive ${project.name}. Please try again.`);
        this.deleting.set(null);
      },
    });
  }

  protected restore(project: Project): void {
    this.deleting.set(project.id);
    this.deleteError.set(null);
    this.service.restore(project.id).subscribe({
      next: (restored) => {
        this.projects.update((list) => list.map((p) => (p.id === restored.id ? restored : p)));
        this.deleting.set(null);
      },
      error: () => {
        this.deleteError.set(`Could not restore ${project.name}. Please try again.`);
        this.deleting.set(null);
      },
    });
  }

  private load(): void {
    this.service.list(this.showArchived(), this.tagFilter()).subscribe((list) => this.projects.set(list));
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

export type ProjectStatus = 'ACTIVE' | 'ON_HOLD' | 'FINISHED';

/** The statuses a project can be marked with, in the order they are offered. */
export const PROJECT_STATUSES: { value: ProjectStatus; label: string }[] = [
  { value: 'ACTIVE', label: 'Active' },
  { value: 'ON_HOLD', label: 'On hold' },
  { value: 'FINISHED', label: 'Finished' },
];

export interface Project {
  id: number;
  name: string;
  clientId: number;
  clientName: string;
  archived: boolean;
  status: ProjectStatus;
}

export interface NewProject {
  name: string;
  clientId: number;
  status: ProjectStatus;
}

@Injectable({ providedIn: 'root' })
export class ProjectService {
  private readonly http = inject(HttpClient);

  list(includeArchived = false, tagId: number | null = null): Observable<Project[]> {
    const params: Record<string, string | number | boolean> = { includeArchived };
    if (tagId !== null) {
      params['tagId'] = tagId;
    }
    return this.http.get<Project[]>('/api/projects', { params });
  }

  listForClient(clientId: number): Observable<Project[]> {
    return this.http.get<Project[]>(`/api/clients/${clientId}/projects`);
  }

  get(id: number): Observable<Project> {
    return this.http.get<Project>(`/api/projects/${id}`);
  }

  create(project: NewProject): Observable<Project> {
    return this.http.post<Project>('/api/projects', project);
  }

  changeStatus(id: number, status: ProjectStatus): Observable<Project> {
    return this.http.put<Project>(`/api/projects/${id}/status`, { status });
  }

  archive(id: number): Observable<Project> {
    return this.http.post<Project>(`/api/projects/${id}/archive`, null);
  }

  restore(id: number): Observable<Project> {
    return this.http.post<Project>(`/api/projects/${id}/restore`, null);
  }
}

